const app = document.querySelector('openclaw-app');
const root = app.shadowRoot || app;
const inputs = [...root.querySelectorAll('input')].map(i => ({placeholder: i.placeholder, type: i.type, value: i.value, id: i.id, name: i.name}));
JSON.stringify(inputs)

function deepActive(root) {
  let el = root.activeElement;
  while (el && el.shadowRoot && el.shadowRoot.activeElement) {
    el = el.shadowRoot.activeElement;
  }
  return el;
}
const el = deepActive(document);
const app = document.querySelector('openclaw-app');
const root = app.shadowRoot;
const pwInput = [...root.querySelectorAll('input[type=password]')][1];
JSON.stringify({activeTag: el ? el.tagName : null, activePlaceholder: el ? el.placeholder : null, pwFieldValue: pwInput ? pwInput.value : 'NOT_FOUND', pwFieldPlaceholder: pwInput ? pwInput.placeholder : null})

const pwInput = document.querySelectorAll('input')[2];
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(pwInput, 'Bymyway7');
pwInput.dispatchEvent(new Event('input', {bubbles: true, composed: true}));
pwInput.dispatchEvent(new Event('change', {bubbles: true, composed: true}));
JSON.stringify({value: pwInput.value})

// Check for any error state stored, and look at localStorage for clues
JSON.stringify({
  localStorage: Object.fromEntries(Object.entries(localStorage)),
  errorText: document.body.innerText.match(/原始錯誤[\s\S]{0,200}/)?.[0]
})

