const app = document.querySelector('openclaw-app');
// list own enumerable + prototype properties that look password/token/connect related
function getAllProps(obj) {
  let props = new Set();
  let cur = obj;
  while (cur) {
    Object.getOwnPropertyNames(cur).forEach(p => props.add(p));
    cur = Object.getPrototypeOf(cur);
  }
  return [...props];
}
const props = getAllProps(app).filter(p => /pass|token|conn|auth|ws|url/i.test(p));
JSON.stringify(props)

const app = document.querySelector('openclaw-app');
const result = app.connect();
JSON.stringify({resultType: typeof result, isPromise: result instanceof Promise})

// simulate what a real user click on Connect does: reload fresh, refill via real events, click button via .click()
location.reload();
'reloading'

