const inputs = [...document.querySelectorAll('input')];
const pw = inputs[2];
const r = pw.getBoundingClientRect();
const btn = [...document.querySelectorAll('button')].find(b => b.textContent.trim() === '連接');
const br = btn.getBoundingClientRect();
JSON.stringify({pwCenter: [r.x + r.width/2, r.y + r.height/2], btnCenter: [br.x + br.width/2, br.y + br.height/2], btnDisabled: btn.disabled})

const inputs = [...document.querySelectorAll('input')];
const btn = [...document.querySelectorAll('button')].find(b => b.textContent.trim() === '連接');
const pw = inputs[2];
const pr = pw ? pw.getBoundingClientRect() : null;
const br = btn ? btn.getBoundingClientRect() : null;
const topAtPw = pr ? document.elementFromPoint(pr.x+pr.width/2, pr.y+pr.height/2) : null;
const topAtBtn = br ? document.elementFromPoint(br.x+br.width/2, br.y+br.height/2) : null;
JSON.stringify({
  inputCount: inputs.length,
  pwRect: pr, btnRect: br,
  topElementAtPasswordField: topAtPw ? (topAtPw.tagName+'.'+topAtPw.className) : null,
  topElementAtButton: topAtBtn ? (topAtBtn.tagName+'.'+topAtBtn.className) : null,
  isPwSameAsTop: topAtPw === pw,
  isBtnSameAsTop: topAtBtn === btn
})

